def square_count(grid, n, m):
    count = 0

    # Count axis-aligned squares
    count += count_axis_aligned(grid, n, m)

    # Count diamond (rotated) squares
    count += count_diamonds(grid, n, m)

    return count


def count_axis_aligned(grid, n, m):
    count = 0
    k = 2  # minimum square size
