        for r in range(n - k + 1):
            for c in range(m - k + 1):
                if is_valid_square(grid, r, c, k, n, m, axis_check=True):
                    count += 1
        k += 1
    return count


def count_diamonds(grid, n, m):
    count = 0
    # Diamond center at (center_r, center_c) with diamond size s (radius)
    # Diamond extends s cells in all diagonal directions from center
    # Minimum diamond size is 2 (2 cells in each diagonal direction from center)
    for center_r in range(n):
