def is_border(r, c, k, i, j):
    """Check if cell (i, j) is on the border of a k x k square at (r, c)"""
    # Top row
    if i == r and c <= j < c + k:
        return True
    # Bottom row
    if i == r + k - 1 and c <= j < c + k:
        return True
    # Left column
    if j == c and r <= i < r + k:
        return True
    # Right column
    if j == c + k - 1 and r <= i < r + k:
        return True
    return False

