def solution(input_str):
    import sys

    # Parse input
    lines = input_str.strip().split('\n')
    n, k = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))

    # Compute Grundy numbers using the most efficient pattern found
    # After analysis, we can use the computed patterns for different k types

    if k % 2 == 0:
        # For even k, pattern is simpler with longer periods
        def compute_grundy(n):
            if n == 0:
                return 0
            if n == 1:
                return 1
            if n == 2:
                return 2
            if n % 4 == 0:
                return 1
            return (n // 2) % 2 + 2 if n >= 2 else 1
    else:
        # For odd k, pattern is 0, 1, 0, 1, 2, ... with some regularities
        def compute_grundy(n):
            if n == 0:
                return 0
            if n == 1:
                return 1
            if n == 2:
                return 0
            if n == 3:
                return 1
            if n == 4:
                return 2
            if n == 5:
                return 0
            if n == 6:
                return 3
            # Pattern: for n=0,1,2,3,4,5 -> 0,1,0,1,2,0, then repeating with offset
            if n % 6 == 0:
                return 0
            elif n % 6 == 1:
                return 1
            elif n % 6 == 2:
                return 0
            elif n % 6 == 3:
                return 1
            elif n % 6 == 4:
                return 2
            else:
                return 0

            # More accurate computation using DP
            memo = {}

            def get_g(n):
                if n == 0:
                    return 0
                if n in memo:
                    return memo[n]

                options = {get_g(n-1)}

                if n % 2 == 0:
                    split_g = get_g(n // 2)
                    if k % 2 == 1:
                        options.add(split_g)
                # For even k, splitting gives 0

                # Compute mex
                mex = 0
                while mex in options:
                    mex += 1
                memo[n] = mex
                return mex

    # Compute XOR of all Grundy numbers
    xor_sum = 0
    for val in a:
        g = get_g(val)
        xor_sum ^= g

    if xor_sum > 0:
        return "Kevin\n"
    else:
        return "Nicky\n"


