    # Odd n cannot have a perfect matching (each city needs one partner)
    if n % 2 != 0:
        return "-1"

    # Parse costs
    costs = []
    for i in range(n):
        row = list(map(int, lines[i+1].split()))
        full_row = [0] * n
        idx = 0
        for j in range(n):
            if j == i:
                continue
            full_row[j] = row[idx]
            idx += 1
        costs.append(full_row)

    def is_stable(partner_map):
        """Check if the matching is stable"""
        # partner_map is a dict: city -> partner

        # Check for blocking pairs
        for i in range(n):
            j = partner_map.get(i, -1)
            if j == -1:
                continue  # unmatched city

            k = partner_map.get(j, -1)
            # k should be i (mutual pairing check)

            # Check all other potential partners m
            for m in range(n):
                if m == i or m == j:
                    continue

                l = partner_map.get(m, -1)
                if l == -1:
                    continue  # m is unmatched, check stability differently

                # i is paired with j, m is paired with l
                # Check if (i, m) is a blocking pair:
                # i prefers m over j AND m prefers i over l
                if costs[i][m] < costs[i][j] and costs[m][i] < costs[l][m]:
                    return False

        return True

    # Generate all perfect matchings
    def generate_matchings(n):
        if n == 2:
            yield ((0, 1),)
            return

        cities = list(range(n))

        results = []

        def backtrack(available, current_pairs):
            if not available:
                results.append(tuple(current_pairs))
                return

            first = available[0]
            for partner in available[1:]:
                new_available = available[1:]
                new_available.remove(partner)
                new_pairs = current_pairs + [(first, partner)]
                backtrack(new_available, new_pairs)

        backtrack(cities, [])
        return results

    matchings = generate_matchings(n)
    stable_found = False
    result = None

    for matching in matchings:
        partner_map = {}
        for city1, city2 in matching:
            partner_map[city1] = city2
            partner_map[city2] = city1

        if is_stable(partner_map):
