                        max_idx = i

                if max_h <= target:
                    break  # All bamboos are at or below target

                # Calculate hits needed to bring this bamboo to target
                hits_needed = max(0, ceil((max_h - target) / p))
                use = min(hits_needed, k - used_hits)

                if use > 0:
                    heights[max_idx] = max(0, heights[max_idx] - use * p)
                    used_hits += use

            # If we couldn't reduce all bamboos below target with available hits
            if max(heights) > target:
                return False

        return True

    # Binary search for minimum feasible target
    # Lower bound: 0
    # Upper bound: initial max + max_growth_rate * m
    lo, hi = 0, max(h for h, a in bamboos) if bamboos else 0 + max(a for h, a in bamboos) if bamboos else 0 + m

    # Ensure upper bound is large enough
    hi = max(hi, 2 * 10**15)

    ans = hi
    while lo <= hi:
        mid = (lo + hi) // 2
        if check(mid):
            ans = mid
            hi = mid - 1
        else:
            lo = mid + 1

    return str(ans)

