import math

def nCr_exact(n, r):
    if r < 0 or r > n:
        return 0
    return math.comb(n, r)

def solve_dp(n, p, l, r):
    # 使用动态规划
    dp = [0] * (n + 1)
    dp[0] = 1

    # 对于 n 个客户中的每一个
    for _ in range(n):
        # 创建一个新的 dp 数组
        next_dp = [0] * (n + 1)
        for j in range(n + 1):
            if dp[j] == 0:
                continue
            # 添加 A: +1
            if j + 1 <= n:
                next_dp[j + 1] = (next_dp[j + 1] + dp[j]) % p

            # 添加 B: -1, only if j > 0
            if j > 0:
                next_dp[j - 1] = (next_dp[j - 1] + dp[j]) % p

            # 添加 C: no change
            next_dp[j] = (next_dp[j] + dp[j]) % p

        dp = next_dp

    # 求和 dp[l] 到 dp[r]
    return sum(dp[l:r+1]) % p

