            return

        for i in range(index, len(candidates)):
            x, y, dist = candidates[i]
            search(i, count + 1, current_points + [(x, y, dist)],
                  current_sum_sq + dist, current_sum_x + x, current_sum_y + y)

    def _calculate_remaining_best(count, remaining):
        max_dist = candidates[0][2] if candidates else 0
        max_score = count * max_dist * remaining + 0
        return max_score

    # This is still complex, let me use a simpler approach with pruning
