    best_config = []

    def backtrack(idx, selected_idx, current_points, sum_sq, sum_x, sum_y):
        nonlocal best_score, best_config

        if len(current_points) == n:
            score = sum_sq * n - (sum_x * sum_x + sum_y * sum_y)
            if score > best_score:
                best_score = score
                best_config = [(p[0], p[1]) for p in current_points]
