        for i in range(idx, min(idx + 200, len(candidates))):
            max_remaining_dist = max(max_remaining_dist, candidates[i][2])

        if sum_sq * n + max_remaining_dist * n > best_score:
            for i in range(idx, min(idx + 100, len(candidates))):
                x, y, dist = candidates[i]
                current_points.append((x, y, dist))
                backtrack(i, selected_idx + 1, current_points, sum_sq + dist, sum_x + x, sum_y + y)
                current_points.pop()

    backtrack(0, 0, [], 0, 0, 0)

    # If not found, use a fallback strategy
    if not config:
        # Try the simplest optimal configuration
        # For even n: n/2 at P and n/2 at -P where P is farthest
        if len(candidates) > 0:
            px, py, pdist = candidates[0]
            half = n // 2
            config = []
            mask = None
            if len(candidates) >= 2:
                nx, ny, ndist = candidates[1]
                if pdist >= ndist:
