                for _ in range(half):
                    config.append(f"{mask[0]} {mask[1]}")
                for _ in range(half):
                    config.append(f"{-mask[0]} {-mask[1]}")
                if config and len(config) == n:
                    found = True

            if found:
                sum_sq = pdist * n
                best_score = sum_sq * n
                best_config = [(int(x), int(y)) for x, y in [config[i//2].split()] for i in range(0, len(config), 2)]

    # Proper fallback
