        dist = [-1] * (n + 1)
        dist[start] = 0
        queue = deque([start])
        max_node, max_d = start, 0
        while queue:
            node = queue.popleft()
            if dist[node] > max_d:
                max_d = dist[node]
                max_node = node
            for neighbor in adj[node]:
                if dist[neighbor] == -1:
                    dist[neighbor] = dist[node] + 1
                    queue.append(neighbor)
