def count_K(N):
    ans = 0
    l = 1
    while l <= N:
        val = N // l
        if val == 0:
            r = N
        else:
            r = N // val
            # Ensure r doesn't exceed N
            if r > N: 
                r = N # Should not happen if logic correct
