    # Direction vectors (up, down, left, right)
    dr = [-1, 1, 0, 0]
    dc = [0, 0, -1, 1]
    dir_names = ['U', 'D', 'L', 'R']

    queue = deque([(0, 0, "")])  # (row, col, path)
    visited = {(0, 0)}

