from collections import deque, defaultdict

def solution(input_data):
    lines = input_data.strip().split('\n')
    idx = 0

    n, m = map(int, lines[idx].split())
    idx += 1

    graph = defaultdict(list)
    for _ in range(m):
        a, b, l = map(int, lines[idx].split())
        idx += 1
        graph[a].append((b, l))

    q = int(lines[idx])
    idx += 1

    queries = []
    for _ in range(q):
        v, s, t = map(int, lines[idx].split())
        idx += 1
        queries.append((v, s, t))

    # Tarjan's algorithm for SCCs
    id_counter = 0
    visited = [False] * (n + 1)
    stack = []
    on_stack = [False] * (n + 1)
    ids = [-1] * (n + 1)
    low = [-1] * (n + 1)
    sccs = []

    def dfs(u):
        nonlocal id_counter
        visited[u] = True
        ids[u] = low[u] = id_counter
        id_counter += 1
        stack.append(u)
        on_stack[u] = True

        for v, _ in graph[u]:
            if not visited[v]:
                dfs(v)
                low[u] = min(low[u], low[v])
            elif on_stack[v]:
                low[u] = min(low[u], ids[v])

        if low[u] == ids[u]:
            scc = []
            while True:
                v = stack.pop()
                on_stack[v] = False
                scc.append(v)
                if v == u:
                    break
            sccs.append(scc)

    for i in range(1, n + 1):
        if not visited[i]:
            dfs(i)

    # Map nodes to SCC IDs
    scc_map = {}
    for scc_id, scc in enumerate(sccs):
        for node in scc:
            scc_map[node] = scc_id

    # Compute GCD of cycle lengths for each SCC
    scc_gcds = [0] * len(sccs)
    for scc_id, scc in enumerate(sccs):
        if len(scc) <= 1:
            scc_gcds[scc_id] = 0
            continue

        # BFS from first node in SCC to compute potentials
        root = scc[0]
        potentials = {root: 0}
        queue = deque([root])

        gcd_val = 0

        while queue:
            u = queue.popleft()
            for v, w in graph[u]:
                if v not in scc_map:
                    continue

                if v not in potentials:
                    potentials[v] = potentials[u] + w
                    queue.append(v)
                else:
                    # Found a back edge, compute cycle length
                    cycle_length = abs(potentials[u] + w - potentials[v])
                    gcd_val = math.gcd(gcd_val, cycle_length)

        scc_gcds[scc_id] = gcd_val

    # Process queries
    results = []
    for v, s, t in queries:
        scc_id = scc_map[v]
        g = scc_gcds[scc_id]

        if g == 0:
            # No cycles through v, only distance 0 is possible
            if s % t == 0:
                results.append("YES")
            else:
                results.append("NO")
        else:
            # Check if s % gcd(g, t) == 0
            if s % math.gcd(g, t) == 0:
                results.append("YES")
            else:
                results.append("NO")

    return '\n'.join(results)

