        parts = line.split()
        pattern_int = int(parts[0], 2)
        req = int(parts[1])
        patterns.append((pattern_int, req))

    @lru_cache(None)
    def backtrack(pos, *matches):
        if pos == n:
            return 1 if all(matches[i] == patterns[i][1] for i in range(m)) else 0

        count = 0
        for try_bit in [0, 1]:
            new_matches = list(matches)
            valid = True

            for i in range(m):
                if patterns[i][pos] == try_bit:
                    valid = (new_matches[i] < patterns[i][1])
                    if valid:
                        new_matches[i] += 1

            if valid:
                count += backtrack(pos + 1, *new_matches)

        return count

    if m == 0:
        return str(1 << n)

    return str(backtrack(0, *[0] * m))

MOD = 1000000007

def gaussian(m, d):
    if d < 0 or d > m:
        return 0
    if d == 0 or d == m:
        return 1

    numerator = 1
    denominator = 1
    for i in range(d):
        numerator = (numerator * (pow(2, m - i) - 1)) % MOD
        denominator = (denominator * (pow(2, d - i) - 1)) % MOD

    return (numerator * pow(denominator, MOD - 2, MOD)) % MOD

