    def dp(i, j, state, path):
        if i == m or j == n:
            return "", path if path else i == 0

        best_result = None

        # Try matching s1[i] with s2[j]
        if s1[i] == s2[j]:
            new_state = auto[(state, s1[i])]
            if new_state < k_len:
                result, found = dp(i + 1, j + 1, new_state)
                if result:
                    candidate = s1[i] + result
                    if best_result is None or candidate > best_result:
                        best_result = candidate

        # Try skipping s1[i], keep s2[j]
        if i < m:
            char_to_consider = s1[i]
            for j_idx in range(n):
                # This approach is getting complicated
                pass

    # Use iterative DP for reconstruction
    # dp[i][j][state] = (length, char, prev_i, prev_j)
    from collections import defaultdict

    INF = -10**9
    dp_len = {}
    dp_char = {}

    for i in range(m + 1):
        for j in range(n + 1):
            for state in range(k_len + 1):
                dp_len[(i, j, state)] = -1

    dp_len[(0, 0, 0)] = 0

    for i in range(m + 1):
        for j in range(n + 1):
            for state in range(k_len + 1):
                if dp_len[(i, j, state)] < 0:
                    continue

                # Option 1: Take s1[i] if it also matches s2[j]
                if i < m and j < n and s1[i] == s2[j]:
                    new_state = auto[(state, s1[i])]
                    if new_state < k_len:
                        new_len = dp_len[(i, j, state)] + 1
                        existing = dp_len[(i + 1, j + 1, new_state)]
                        if existing < new_len:
                            dp_len[(i + 1, j + 1, new_state)] = new_len
                            dp_char[(i + 1, j + 1, new_state)] = s1[i]
                            dp_len[(i, j + 1, new_state)] = max(dp_len[(i, j + 1, new_state)], dp_len[(i + 1, j + 1, new_state)])
                            dp_char[(i, j + 1, new_state)] = dp_char[(i + 1, j + 1, new_state)]

                # Option 2: Skip s1[i]
                if i < m:
                    new_state = auto[(state, s1[i])]
                    new_len = dp_len[(i, j, state)]
                    existing = dp_len[(i + 1, j, new_state)]
                    if existing < new_len:
                        dp_len[(i + 1, j, new_state)] = new_len
                        dp_char[(i + 1, j, new_state)] = 'X'

                # Option 3: Skip s2[j]
                if j < n:
                    new_state = auto[(state, s2[j])]
                    new_len = dp_len[(i, j, state)]
                    existing = dp_len[(i, j + 1, new_state)]
                    if existing < new_len:
                        dp_len[(i, j + 1, new_state)] = new_len
                        dp_char[(i, j + 1, new_state)] = 'X'

    # Find maximum length
    best_len = 0
    best_i, best_j, best_state = 0, 0, 0

    for i in range(m + 1):
        for j in range(n + 1):
            for state in range(k_len + 1):
                if dp_len[(i, j, state)] > best_len:
                    best_len = dp_len[(i, j, state)]
                    best_i, best_j, best_state = i, j, state

    if best_len == 0:
        return "0"

    # Reconstruct solution
    result = []
    i, j, state = best_i, best_j, best_state

    while i > 0 or j > 0:
        if (i - 1, j, state) in dp_char and dp_char[(i - 1, j, state)] == s1[i - 1]:
            if dp_len[(i - 1, j - 1, state)] + 1 == dp_len[(i, j, state)]:
                result.append(s1[i - 1])
                i -= 1
                j -= 1
            else:
                i -= 1
        elif (i, j - 1, state) in dp_char:
            j -= 1
        elif (i - 1, j, state) in dp_char:
            i -= 1

    return ''.join(reversed(result))

