def solution(input_str):
    parts = input_str.strip().split()
    n = int(parts[0])
    k = int(parts[1])

    def orbit_of_s(s):
        """Generate all strings in the equivalence class of s"""
        flipped = ''.join('1' if c == '0' else '0' for c in s)
        return {
            s,
            s[::-1],  # reversal
            flipped,  # color flip
            flipped[::-1]  # reversal + color flip
        }

    def bit_string(k, n):
        """Convert integer to n-bit binary string"""
        return format(k, f'0{n}b')

    # Find all canonical representatives
    representatives = {}

    # For reasonable n, enumerate all strings
    if n <= 60 and (1 << n) <= (1 << 60):
        for i in range(2**n):
            s = bit_string(i, n)
            orbit = orbit_of_s(s)
            minimal = min(orbit)  # lexicographically smallest
            if minimal not in representatives:
                representatives[minimal] = True

        sorted_reps = sorted(representatives.keys())

        if k > len(sorted_reps):
            return "-1\n"
        return sorted_reps[k-1] + "\n"
    else:
        return "-1\n"

def solution(input_data):
    import sys

    data = input_data.strip().split('\n')
    if not data:
        return ''

    first_line = data[0].split()
    n, m = int(first_line[0]), int(first_line[1])

    frogs = []
    for i in range(n):
        parts = data[i+1].split()
        pos = int(parts[0])
        a = int(parts[1])
        frogs.append([i + 1, pos - 1, a, True])  # 0-indexed pos

    # Use sorted list of (pos, orig_idx) for efficient range queries
    from bisect import bisect_left, bisect_right

    sorted_frogs = sorted([(f[1], f[0]) for f in frogs if f[3]])

    # List of (pos, orig_idx, new_a, alive) for current state
    current_pos_list = []  # parallel to frogs

    for turn in range(n * 200000):  # Heuristic bound for termination
        has_frog = False

        for frog_idx in range(n):
            fid, pos, a, alive = frogs[frog_idx]

            if not alive or a <= 0:
                continue

            has_frog = True

            landing_pos = (pos + a) % m

            # Find frogs in path: from pos+1 to landing_pos (inclusive)
            new_knocks = 0

            if a >= m:
                # Jump covers entire board
                path_frogs = [ft for ft in sorted_frogs if ft[1] != fid][1]  # Remove self
            elif landing_pos > pos:
                # No wrap: pos+1 to landing_pos
                start_idx = bisect_left(sorted_frogs, (pos + 1, 0))
                end_idx = bisect_right(sorted_frogs, (landing_pos, 10**18)) - 1
                found = []
                for i in range(start_idx, end_idx + 1):
                    if sorted_frogs[i][1] != fid:
                        found.append(i)
                path_frogs = found
            elif landing_pos == pos:
                # Self-loop - just passes through other frogs
                start_idx = bisect_left(sorted_frogs, (0, 0))
                end_idx = bisect_right(sorted_frogs, (m - 1, 10**18)) - 1 if a < m else None
                if end_idx is not None:
                    for i in range(start_idx, end_idx):
                        if sorted_frogs[i][1] != fid:
                            path_frogs.append(i)
                else:
                    for ft in sorted_frogs:
                        if ft[1] != fid:
                            path_frogs.append(sorted_frogs.index((ft[1], ft[0])))
            else:
                # Wrap: pos+1 to m-1, then 0 to landing_pos
                found1 = []
                start1 = bisect_left(sorted_frogs, (pos + 1, 0))
                end1 = bisect_right(sorted_frogs, (m - 1, 10**18)) - 1
                for i in range(start1, end1 + 1):
                    if sorted_frogs[i][1] != fid:
                        found1.append(i)

                found2 = []
                start2 = bisect_left(sorted_frogs, (0, 0))
                end2 = bisect_right(sorted_frogs, (landing_pos, 10**18)) - 1
                for i in range(start2, end2 + 1):
                    if sorted_frogs[i][1] != fid:
                        found2.append(i)

                path_frogs = found1 + found2

            knocked_count = len(path_frogs)
            if knocked_count > 0:
                for idx in path_frogs:
                    orig_idx = sorted_frogs[idx][1]
                    for i in range(n):
                        if frogs[i][0] == orig_idx:
                            frogs[i][2] = max(0, frogs[i][2] - 1)
                            frogs[i][3] = False
                            break

                new_a = a - knocked_count - 1
                frogs[frog_idx][2] = max(0, new_a)

        # Check convergence
        if not has_frog:
            break

    remaining = [f for f in frogs if f[3]]
    remaining.sort(key=lambda x: x[0])

    result_lines = [str(len(remaining))]
    result_lines.append(' '.join(str(f[0]) for f in remaining))
    return '\n'.join(result_lines)
